SELECT 
FROM quality_inspection_order
WHERE is_deleted = 0

    AND (order_no LIKE CONCAT('%', #{keyword}, '%')
         OR product_code LIKE CONCAT('%', #{keyword}, '%')
         OR product_name LIKE CONCAT('%', #{keyword}, '%'))


    AND order_type = #{orderType}


    AND result = #{result}

ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM quality_inspection_order WHERE is_deleted = 0
AND (order_no LIKE CONCAT('%', #{keyword}, '%') OR product_code LIKE CONCAT('%', #{keyword}, '%') OR product_name LIKE CONCAT('%', #{keyword}, '%'))
AND order_type = #{orderType}
AND result = #{result}
